(function(){
  const E = (id,title,chapter,concept,syntax,example,explanation,output,uses,notes,mistakes,takeaways,prerequisites=[]) => ({
    id, slug:id.replace(/^c-/,'').replace(/[^a-z0-9-]/g,'-'), title, chapter, difficulty:'beginner', estimatedTime:12,
    prerequisites, description:concept, objectives:[`Giải thích được ${title}.`,`Viết được ví dụ nhỏ dùng ${title}.`,'Nhận diện và sửa lỗi thường gặp.'],
    concept:{title:'Khái niệm',content:concept}, syntax:[{code:syntax,explanation:'Đọc cú pháp từ trái sang phải; thay phần in nghiêng bằng dữ liệu của chương trình.'}],
    examples:[{title:'Ví dụ minh họa',code:example,output,explanation}], useCases:uses, notes, commonMistakes:mistakes,
    keyTakeaways:takeaways, exerciseIds:['c-ex-001'], quiz:[
      {question:`Phát biểu nào đúng về ${title}?`,options:[`Hiểu mục đích và áp dụng được ${title}`,'Chỉ cần chép lại mã','Không cần kiểm tra kết quả','Có thể bỏ qua cú pháp'],answer:0,explanation:`${title} cần được hiểu qua cú pháp, ví dụ và thực hành.`},
      {question:`Khi học ${title}, bước nên làm là gì?`,options:['Đọc, tự gõ, chạy thử và sửa lỗi','Bỏ qua compiler','Xóa mã khi gặp lỗi','Chỉ xem đáp án'],answer:0,explanation:'Thực hành từng bước giúp phát hiện và sửa lỗi sớm.'},
      {question:'Điều gì giúp mã C an toàn, dễ bảo trì hơn?',options:['Kiểm tra input và giới hạn dữ liệu','Dùng biến chưa khởi tạo','Bỏ qua cảnh báo','Truy cập ngoài phạm vi'],answer:0,explanation:'Kiểm tra dữ liệu và giới hạn bộ nhớ là nguyên tắc nền tảng.'}
    ], source:'https://www.w3schools.com/c/'
  });
  const lessons = [
    E('c-intro','C là gì?','C Basics','C là ngôn ngữ lập trình đa mục đích do Dennis Ritchie phát triển tại Bell Labs năm 1972. C tạo chương trình nhanh, kiểm soát bộ nhớ tốt và được dùng trong hệ điều hành, phần mềm nhúng, cơ sở dữ liệu và công cụ hệ thống. C chủ yếu tổ chức chương trình bằng hàm; C++ kế thừa nhiều cú pháp nhưng bổ sung lớp và đối tượng.','#include <stdio.h>\nint main(void) { /* ... */ return 0; }','#include <stdio.h>\n\nint main(void) {\n    printf("Hello, World!\\n");\n    return 0;\n}','#include khai báo printf; main là điểm vào; printf xuất chuỗi; return 0 báo kết thúc thành công.','Hello, World!',['Học nền tảng bộ nhớ và hiệu năng','Viết hệ điều hành, firmware và thư viện hệ thống'],['C là ngôn ngữ biên dịch nên mã nguồn cần qua compiler.','Tên file nguồn thường kết thúc bằng .c.'],[['printf(Hello);','Chuỗi chưa đặt trong dấu ngoặc kép.','printf("Hello");']],['C nhanh và gần phần cứng.','Chương trình bắt đầu ở main.','printf dùng để xuất dữ liệu.']),
    E('c-get-started','Cài đặt môi trường C','C Basics','Editor là nơi viết mã; compiler như GCC dịch mã C thành chương trình thực thi; IDE kết hợp editor, build và debug. Quy trình học là viết, lưu .c, biên dịch, đọc lỗi rồi chạy.','gcc main.c -o main\n./main','#include <stdio.h>\nint main(void) {\n    printf("Da chay chuong trinh C");\n    return 0;\n}','GCC nhận main.c và tạo tệp thực thi main. Tùy hệ điều hành, lệnh chạy có thể là ./main hoặc main.exe.','Da chay chuong trinh C',['Dùng GCC trên terminal','Dùng Code::Blocks, VS Code hoặc IDE khác'],['Bật cảnh báo -Wall -Wextra khi học.'],[['Lưu thành main.txt','Compiler không nhận đúng loại file.','Lưu thành main.c.']],['Editor viết mã.','Compiler dịch mã.','Compile và Run là hai bước khác nhau.'],['c-intro']),
    E('c-syntax','C Syntax','C Basics','Syntax là các quy tắc giúp compiler hiểu chương trình: header, hàm, statement, block và dấu chấm phẩy. C phân biệt chữ hoa/chữ thường; khối lệnh được bao bởi { } và main là điểm bắt đầu thực thi.','#include <stdio.h>\nint main(void) { statement; return 0; }','#include <stdio.h>\n\nint main(void) {\n    int age = 18;\n    if (age >= 18) {\n        printf("Adult");\n    }\n    return 0;\n}','statement int age = 18; kết thúc bằng ;. Block của if chỉ chạy khi điều kiện đúng.','Adult',['Đọc lỗi cú pháp','Định dạng code nhất quán'],['Khoảng trắng không đổi ý nghĩa nhưng đổi khả năng đọc.'],[['int age = 18','Thiếu dấu ;.','int age = 18;']],['C phân biệt hoa thường.','Statement thường có ;.','Block dùng { }.'],['c-get-started']),
    E('c-comments','Comments','C Basics','Comment là ghi chú dành cho người đọc và bị compiler bỏ qua. Dùng // cho một dòng; dùng /* ... */ cho nhiều dòng hoặc tạm vô hiệu hóa code khi kiểm thử.','// một dòng\n/* nhiều dòng */','#include <stdio.h>\n\nint main(void) {\n    // printf("Khong chay");\n    printf("Dang chay");\n    return 0;\n}','Dòng có // bị bỏ qua nên chỉ chuỗi Dang chay xuất hiện.','Dang chay',['Ghi lý do của đoạn code','Tạm tắt lệnh khi debug'],['Comment nên giải thích ý định, không lặp lại tên biến.'],[['/* comment','Thiếu */ làm hỏng phần còn lại của file.','/* comment da dong */']],['Comment không tạo output.','Có hai kiểu comment chính.','Dùng comment có mục đích.'],['c-syntax']),
    E('c-output','Output với printf','C Basics','printf nhận chuỗi định dạng và các giá trị đi kèm để in ra màn hình. %d dùng cho int, %f cho số thực, %c cho char, %s cho chuỗi; \\n tạo dòng mới.','printf("%d %.2f %c %s\\n", integer, decimal, character, text);','#include <stdio.h>\n\nint main(void) {\n    int age = 20;\n    double score = 8.5;\n    char grade = \'A\';\n    printf("Age: %d\\nScore: %.1f\\nGrade: %c\\n", age, score, grade);\n    return 0;\n}','Mỗi placeholder khớp với một đối số. %.1f in một chữ số sau dấu chấm.','Age: 20\nScore: 8.5\nGrade: A',['Hiển thị kết quả','In thông tin debug'],['Số placeholder và kiểu dữ liệu phải khớp.'],[['printf(age);','printf cần chuỗi định dạng.','printf("%d", age);']],['printf xuất dữ liệu.','Specifier phải đúng kiểu.','\\n tạo dòng mới.'],['c-syntax']),
    E('c-compile-errors','Biên dịch và đọc lỗi','C Basics','Compiler có thể báo lỗi cú pháp, cảnh báo hoặc lỗi liên kết. Lỗi runtime xảy ra khi chương trình chạy; lỗi logic cho kết quả sai dù compile thành công. Hãy sửa lỗi đầu tiên trong thông báo và biên dịch lại.','gcc -std=c11 -Wall -Wextra main.c -o main','#include <stdio.h>\n\nint main(void) {\n    int number = 10;\n    printf("%d\\n", number);\n    return 0;\n}','-Wall và -Wextra giúp phát hiện biến chưa dùng, kiểu không khớp và nhiều lỗi tiềm ẩn.','10',['Debug chương trình','Kiểm tra code trước khi nộp bài'],['Không bỏ qua warning một cách máy móc.'],[['printf("%d", 3.14);','Specifier không khớp kiểu.','printf("%.2f", 3.14);']],['Đọc lỗi từ dòng đầu tiên.','Warning đáng được xem xét.','Compile không chứng minh thuật toán đúng.'],['c-syntax']),
    E('c-variables','Variables','Variables & Data Types','Biến là một vùng lưu trữ có tên và kiểu dữ liệu. Có thể hình dung biến như chiếc hộp: khai báo tạo chiếc hộp, khởi tạo đặt giá trị vào, phép gán thay đổi giá trị trong khi chương trình chạy.','type variableName = value;','#include <stdio.h>\n\nint main(void) {\n    int age = 20;\n    float height = 1.75f;\n    char grade = \'A\';\n    age = 21;\n    printf("%d %.2f %c", age, height, grade);\n    return 0;\n}','int, float và char là kiểu; age, height, grade là tên; các giá trị phía sau dấu = là giá trị ban đầu.','21 1.75 A',['Lưu dữ liệu người dùng','Tính toán và giữ trạng thái'],['Khởi tạo biến trước khi đọc.','Dấu = là phép gán.'],[['int 1age = 20;','Tên biến không thể bắt đầu bằng số.','int age1 = 20;']],['Mỗi biến có kiểu.','Có thể gán lại giá trị.','Tên biến nên có ý nghĩa.'],['c-syntax']),
    E('c-variable-naming','Quy tắc đặt tên biến','Variables & Data Types','Tên định danh C chỉ dùng chữ cái, chữ số và dấu gạch dưới; không được bắt đầu bằng chữ số, không có khoảng trắng và không trùng keyword. C phân biệt total và Total.','identifier: letter_or_underscore followed by letters, digits, underscores','#include <stdio.h>\n\nint main(void) {\n    int student_count = 3;\n    printf("%d", student_count);\n    return 0;\n}','student_count dùng snake_case, rõ nghĩa và hợp lệ. Quy ước nhất quán làm code dễ đọc.','3',['Đặt tên API và biến bền vững','Làm việc nhóm'],['Tránh tên một chữ cái trừ biến đếm rất ngắn.'],[['int student-count = 3;','Dấu - là toán tử trừ.','int student_count = 3;']],['Không bắt đầu bằng số.','Không dùng keyword.','Ưu tiên tên mô tả.'],['c-variables']),
    E('c-data-types','Data Types','Variables & Data Types','Kiểu dữ liệu mô tả dạng giá trị biến giữ và cách compiler bố trí bộ nhớ. int dành cho số nguyên; float/double cho số thực; char cho một ký tự; short, long, signed và unsigned điều chỉnh miền giá trị.','int, float, double, char, short, long, signed, unsigned','#include <stdio.h>\n\nint main(void) {\n    int count = 10;\n    unsigned int total = 20u;\n    double price = 19.99;\n    char symbol = \'$\';\n    printf("%d %u %.2f %c", count, total, price, symbol);\n    return 0;\n}','Mỗi format specifier được chọn theo kiểu. unsigned không biểu diễn số âm; double thường có độ chính xác cao hơn float.','10 20 19.99 $',['Chọn kiểu đúng miền giá trị','Tối ưu bộ nhớ khi cần'],['Kích thước chính xác phụ thuộc nền tảng; dùng sizeof để kiểm tra.'],[['unsigned int n = -1;','Giá trị âm không phù hợp unsigned.','int n = -1;']],['Kiểu quyết định cách lưu.','Specifier phải khớp kiểu.','Kích thước không nên đoán.'],['c-variables']),
    E('c-characters','Characters','Variables & Data Types','char lưu một ký tự, viết trong dấu nháy đơn. Bên trong, ký tự có một mã số; vì vậy char có thể tham gia phép tính nhưng không nên nhầm một char với chuỗi char[].','char letter = \'A\';','#include <stdio.h>\n\nint main(void) {\n    char letter = \'A\';\n    printf("%c %d", letter, letter);\n    return 0;\n}','%c in ký tự A; %d in mã số tương ứng theo execution character set.','A 65',['Xử lý ký tự nhập','Kiểm tra chữ hoa/chữ thường'],['Dấu nháy đơn cho một char; dấu kép cho chuỗi.'],[['char c = "A";','"A" là chuỗi, không phải char.','char c = \'A\';']],['char lưu một ký tự.','Dùng nháy đơn.','Mã ký tự có thể in bằng %d.'],['c-data-types']),
    E('c-strings','Strings','Variables & Data Types','Chuỗi trong C là dãy char kết thúc bằng ký tự null \\0. Không có kiểu string dựng sẵn; chương trình dùng mảng ký tự và các hàm trong string.h.','char text[] = "Hello";','#include <stdio.h>\n\nint main(void) {\n    char text[] = "Hello";\n    printf("%s", text);\n    return 0;\n}','Compiler thêm \\0 sau ký tự cuối. Mảng phải có đủ chỗ cho ký tự kết thúc.','Hello',['Lưu tên và dòng văn bản','Trao đổi dữ liệu dạng text'],['Không ghi quá giới hạn mảng char.'],[['char text[5] = "Hello";','Cần thêm chỗ cho \\0.','char text[6] = "Hello";']],['Chuỗi là mảng char.','Chuỗi kết thúc bằng \\0.','Cần kiểm soát kích thước.'],['c-characters']),
    E('c-numbers','Numbers','Variables & Data Types','C biểu diễn số nguyên và số thực khác nhau. Phép chia giữa hai int cho kết quả int; muốn giữ phần thập phân, ít nhất một toán hạng phải là float hoặc double.','int whole = 7 / 2;\ndouble real = 7.0 / 2;','#include <stdio.h>\n\nint main(void) {\n    int whole = 7 / 2;\n    double real = 7.0 / 2;\n    printf("%d %.1f", whole, real);\n    return 0;\n}','7 / 2 là 3; 7.0 / 2 là 3.5 vì phép tính được nâng lên số thực.','3 3.5',['Tính tiền, điểm, tỷ lệ','Xử lý số đo'],['Dùng double khi cần độ chính xác tốt hơn float.'],[['double result = 7 / 2;','Phép chia xảy ra khi cả hai toán hạng là int.','double result = 7.0 / 2;']],['Số nguyên và số thực khác nhau.','Phép chia int làm mất phần lẻ.','Dùng ép kiểu khi cần.'],['c-data-types']),
    E('c-sizeof','sizeof và kích thước bộ nhớ','Variables & Data Types','sizeof là toán tử trả về số byte mà một kiểu hoặc biến chiếm trên nền tảng hiện tại. Kết quả có kiểu size_t, nên dùng %zu khi in.','sizeof(type)\nsizeof expression','#include <stdio.h>\n\nint main(void) {\n    int values[4];\n    printf("int=%zu array=%zu", sizeof(int), sizeof values);\n    return 0;\n}','sizeof values trả về toàn bộ mảng, không phải số phần tử; số phần tử có thể tính bằng sizeof values / sizeof values[0].','int=4 array=16',['Tính số phần tử mảng tĩnh','Kiểm tra layout dữ liệu'],['Không giả định int luôn 4 byte.'],[['printf("%d", sizeof(int));','sizeof không nhất thiết là int.','printf("%zu", sizeof(int));']],['sizeof tính theo byte.','Kích thước phụ thuộc nền tảng.','size_t dùng cho kích thước.'],['c-data-types']),
    E('c-constants','Constants','Variables & Data Types','Hằng số biểu diễn giá trị không nên thay đổi. const tạo đối tượng có kiểu và được compiler kiểm tra; #define tạo macro thay thế văn bản trước khi biên dịch.','const type NAME = value;\n#define NAME value','#include <stdio.h>\n#define MAX_USERS 100\n\nint main(void) {\n    const double PI = 3.14159;\n    printf("%d %.5f", MAX_USERS, PI);\n    return 0;\n}','PI được kiểm tra như một double; MAX_USERS được thay thế bằng 100 ở bước tiền xử lý.','100 3.14159',['Đặt giới hạn và cấu hình','Tránh số ma thuật'],['Ưu tiên const khi cần kiểu và phạm vi rõ.'],[['const int LIMIT;','const phải được khởi tạo trước khi đọc.','const int LIMIT = 100;']],['const tạo giá trị chỉ đọc.','define là macro.','Hằng giúp code dễ bảo trì.'],['c-variables']),
    E('c-type-conversion','Type Conversion','Variables & Data Types','Chuyển kiểu biến đổi giá trị giữa các kiểu. Chuyển ngầm định có thể xảy ra khi biểu thức trộn kiểu; ép kiểu tường minh dùng (type)value và làm rõ ý định.','(type) expression','#include <stdio.h>\n\nint main(void) {\n    int a = 5, b = 2;\n    double result = (double)a / b;\n    printf("%.2f", result);\n    return 0;\n}','Ép a sang double trước phép chia nên kết quả giữ được 2.50 thay vì 2.','2.50',['Tính tỷ lệ và phần trăm','Giao tiếp API khác kiểu'],['Chuyển kiểu nhỏ hơn có thể mất dữ liệu hoặc gây tràn.'],[['int x = (int)3.9;','Phần thập phân bị loại bỏ.','double x = 3.9;']],['Có chuyển kiểu ngầm định và tường minh.','Ép kiểu ảnh hưởng phép tính.','Cần cân nhắc mất dữ liệu.'],['c-data-types']),
    E('c-arithmetic','Arithmetic Operators','Operators','Toán tử số học gồm +, -, *, / và %. Chúng xử lý số; % trả phần dư và chỉ áp dụng trực tiếp cho số nguyên.','a + b; a - b; a * b; a / b; a % b;','#include <stdio.h>\n\nint main(void) {\n    int a = 10, b = 3;\n    printf("%d %d %d %d %d", a+b, a-b, a*b, a/b, a%b);\n    return 0;\n}','Kết quả lần lượt là 13, 7, 30, 3 và 1; phép chia int bỏ phần lẻ.','13 7 30 3 1',['Tính toán số lượng và chỉ số','Kiểm tra số chẵn lẻ'],['Dùng ngoặc khi biểu thức nhiều toán tử.'],[['int r = 10 % 0;','Chia cho 0 là lỗi runtime/undefined behavior.','Kiểm tra mẫu số trước.']],['Có 5 toán tử số học cơ bản.','% lấy phần dư.','Chia int cần chú ý.'],['c-type-conversion']),
    E('c-assignment','Assignment Operators','Operators','Toán tử gán đặt hoặc cập nhật giá trị của biến. Ngoài =, các dạng +=, -=, *=, /= và %= kết hợp phép tính với phép gán.','variable = expression;\nvariable += value;','#include <stdio.h>\n\nint main(void) {\n    int score = 10;\n    score += 5;\n    score *= 2;\n    printf("%d", score);\n    return 0;\n}','score += 5 tương đương score = score + 5; sau đó nhân đôi thành 30.','30',['Cập nhật bộ đếm','Tích lũy tổng và trạng thái'],['Vế phải được tính trước khi gán.'],[['if (x = 3)','Vô tình gán thay vì so sánh.','if (x == 3)']],['= là phép gán.','Dạng rút gọn ngắn hơn.','Kiểm tra kiểu khi gán.'],['c-arithmetic']),
    E('c-comparison','Comparison Operators','Operators','Toán tử so sánh đối chiếu hai giá trị và tạo kết quả đúng/sai. Gồm ==, !=, >, <, >= và <=; kết quả thường dùng trong điều kiện.','left == right; left != right; left >= right;','#include <stdio.h>\n\nint main(void) {\n    int age = 20;\n    printf("%d %d", age >= 18, age == 20);\n    return 0;\n}','C coi 1 là đúng và 0 là sai trong biểu thức in ra; == không thay đổi biến.','1 1',['Kiểm tra điều kiện','Lọc dữ liệu'],['Đặt hằng bên trái khi phù hợp để compiler bắt lỗi gán nhầm.'],[['if (age = 18)','Đây là phép gán luôn trả giá trị 18.','if (age == 18)']],['So sánh tạo điều kiện.','== khác =.','Kết quả thường là 0 hoặc 1.'],['c-assignment']),
    E('c-logical','Logical Operators','Operators','&& yêu cầu cả hai điều kiện đúng; || yêu cầu ít nhất một điều kiện đúng; ! đảo kết quả. C có short-circuit nên vế sau có thể không được đánh giá.','conditionA && conditionB\nconditionA || conditionB\n!condition','#include <stdio.h>\n\nint main(void) {\n    int age = 20, hasCard = 1;\n    if (age >= 18 && hasCard) printf("Allowed");\n    return 0;\n}','Cả age >= 18 và hasCard đều đúng nên thân if chạy.','Allowed',['Ghép điều kiện form','Kiểm tra quyền truy cập'],['Đừng phụ thuộc side effect ở vế có thể bị short-circuit.'],[['if (a > 0 & b > 0)','& là bitwise, không phải logic AND.','if (a > 0 && b > 0)']],['&& là và.','|| là hoặc.','! phủ định.'],['c-comparison']),
    E('c-increment','Increment và Decrement','Operators','++ tăng một đơn vị và -- giảm một đơn vị. Prefix thay đổi trước khi biểu thức lấy giá trị; postfix lấy giá trị cũ rồi mới thay đổi.','++variable; variable++; --variable; variable--;','#include <stdio.h>\n\nint main(void) {\n    int x = 5;\n    printf("%d ", x++);\n    printf("%d", ++x);\n    return 0;\n}','x++ in 5 rồi x thành 6; ++x tăng thành 7 rồi in 7.','5 7',['Bộ đếm vòng lặp','Di chuyển qua chỉ số'],['Tránh tăng cùng biến nhiều lần trong một biểu thức phức tạp.'],[['int y = x++ + ++x;','Thứ tự thay đổi khó đọc và có thể undefined.','Tách thành nhiều statement.']],['++/-- thay đổi một đơn vị.','Prefix và postfix khác thời điểm.','Dùng rõ ràng trong biểu thức.'],['c-assignment']),
    E('c-precedence','Operator Precedence','Operators','Khi biểu thức có nhiều toán tử, precedence và associativity quyết định thứ tự tính. Ngoặc tròn có ưu tiên cao và là cách rõ nhất để thể hiện ý định.','(expression)\n* / %\n+ -','#include <stdio.h>\n\nint main(void) {\n    int a = 2 + 3 * 4;\n    int b = (2 + 3) * 4;\n    printf("%d %d", a, b);\n    return 0;\n}','a là 14 vì nhân trước cộng; b là 20 vì ngoặc buộc cộng trước.','14 20',['Viết công thức rõ ràng','Tránh bug do thứ tự tính'],['Tách biểu thức phức tạp thành biến trung gian khi cần.'],[['int r = a + b * c;','Người đọc có thể hiểu nhầm ý định.','int r = a + (b * c);']],['Ngoặc giúp rõ ý.','Nhân/chia trước cộng/trừ.','Không phụ thuộc trí nhớ khi biểu thức dài.'],['c-arithmetic']),
    E('c-booleans','Booleans','Conditions','C dùng 0 là false và mọi giá trị khác 0 là true. Header stdbool.h cung cấp bool, true và false để biểu đạt ý định rõ hơn.','#include <stdbool.h>\nbool ready = true;','#include <stdio.h>\n#include <stdbool.h>\n\nint main(void) {\n    bool ready = true;\n    printf("%s", ready ? "yes" : "no");\n    return 0;\n}','ready có kiểu bool và giá trị true, giúp code nói rõ đây là trạng thái chứ không phải số tùy ý.','yes',['Trạng thái bật/tắt','Điều kiện có/không'],['stdbool.h có từ C99.'],[['if (ready = true)','Gán true thay vì so sánh; làm mất trạng thái cũ.','if (ready)']],['0 là false.','Khác 0 là true.','bool làm ý định rõ hơn.'],['c-logical']),
    E('c-if','if','Conditions','if kiểm tra một điều kiện và chỉ chạy block khi điều kiện có giá trị đúng. Điều kiện có thể là so sánh, biến bool hoặc biểu thức logic.','if (condition) { statements; }','#include <stdio.h>\n\nint main(void) {\n    int score = 8;\n    if (score >= 5) {\n        printf("Pass");\n    }\n    return 0;\n}','score >= 5 đúng nên statement trong block được thực hiện.','Pass',['Kiểm tra điều kiện đơn','Bảo vệ thao tác trước khi thực hiện'],['Luôn dùng block dù chỉ có một statement để tránh lỗi khi mở rộng.'],[['if score >= 5','C thiếu ngoặc quanh điều kiện.','if (score >= 5)']],['if chọn theo điều kiện.','Block chỉ chạy khi đúng.','Dùng ngoặc nhọn.'],['c-booleans']),
    E('c-if-else','if else','Conditions','if else chia hai đường đi: một block cho điều kiện đúng và một block cho điều kiện sai. Đây là cấu trúc phù hợp khi chỉ có hai trường hợp loại trừ nhau.','if (condition) { ... } else { ... }','#include <stdio.h>\n\nint main(void) {\n    int number = 7;\n    if (number % 2 == 0) printf("Even");\n    else printf("Odd");\n    return 0;\n}','number % 2 bằng 1 nên nhánh else in Odd.','Odd',['Phân loại dữ liệu','Kiểm tra hợp lệ/không hợp lệ'],['else gắn với if gần nhất chưa có else.'],[['if (x == 1));','Dư dấu ; làm if rỗng.','if (x == 1) { ... }']],['else xử lý trường hợp sai.','Hai nhánh loại trừ nhau.','Có thể dùng block rõ ràng.'],['c-if']),
    E('c-else-if','else if','Conditions','else if cho phép kiểm tra nhiều điều kiện theo thứ tự. Khi gặp nhánh đầu tiên đúng, các nhánh còn lại không được xét tiếp.','if (...) { ... } else if (...) { ... } else { ... }','#include <stdio.h>\n\nint main(void) {\n    int score = 82;\n    if (score >= 90) printf("A");\n    else if (score >= 80) printf("B");\n    else printf("C");\n    return 0;\n}','82 không đạt 90 nhưng đạt 80 nên in B.','B',['Xếp loại điểm','Phân tầng mức độ'],['Sắp xếp điều kiện từ cụ thể/cao xuống thấp để không bắt nhầm nhánh.'],[['if (score >= 50) ... else if (score >= 80)','Nhánh 50 chặn nhánh 80.','Đặt điều kiện 80 trước.']],['Nhánh được xét từ trên xuống.','Nhánh đầu tiên đúng thắng.','else là mặc định.'],['c-if-else']),
    E('c-nested-if','Nested if','Conditions','Nested if là một if nằm trong block của if khác. Dùng khi điều kiện bên trong chỉ có ý nghĩa sau khi điều kiện bên ngoài đã đúng.','if (outer) { if (inner) { ... } }','#include <stdio.h>\n\nint main(void) {\n    int age = 20, hasId = 1;\n    if (age >= 18) {\n        if (hasId) printf("Allowed");\n    }\n    return 0;\n}','Chỉ khi đủ tuổi và có ID thì thông báo được in.','Allowed',['Kiểm tra nhiều tầng','Phân quyền theo điều kiện'],['Nếu lồng quá sâu, tách thành hàm hoặc dùng điều kiện logic.'],[['if (age >= 18) if (hasId) ...','Thiếu block dễ tạo dangling else.','Dùng { } rõ ràng.']],['Điều kiện ngoài bảo vệ điều kiện trong.','Block giúp ghép logic.','Tránh lồng quá sâu.'],['c-if-else']),
    E('c-switch','switch','Conditions','switch chọn một nhánh dựa trên giá trị nguyên hoặc enum. case là giá trị cụ thể, break ngăn rơi xuống case kế tiếp, default xử lý giá trị khác.','switch (expression) { case constant: statements; break; default: statements; }','#include <stdio.h>\n\nint main(void) {\n    int choice = 2;\n    switch (choice) {\n        case 1: printf("Add"); break;\n        case 2: printf("Edit"); break;\n        default: printf("Other");\n    }\n    return 0;\n}','choice bằng 2 nên chạy case 2 rồi break.','Edit',['Menu lựa chọn','Trạng thái enum'],['switch không phù hợp với điều kiện khoảng như score > 80.'],[['case 1: printf("A");','Thiếu break có thể chạy tiếp case 2.','Thêm break khi không muốn fall-through.']],['case cần giá trị hằng.','break kiểm soát fall-through.','default là đường dự phòng.'],['c-if-else']),
    E('c-while','while','Loops','while kiểm tra điều kiện trước mỗi lượt, nên thân vòng lặp có thể chạy zero lần. Biến điều khiển phải thay đổi để cuối cùng điều kiện thành false.','while (condition) { statements; }','#include <stdio.h>\n\nint main(void) {\n    int i = 1;\n    while (i <= 3) {\n        printf("%d ", i);\n        i++;\n    }\n    return 0;\n}','i tăng sau mỗi lượt và dừng khi i thành 4.','1 2 3 ',['Lặp tới khi gặp sentinel','Đọc dữ liệu nhiều lần'],['Kiểm tra điều kiện trước thân vòng lặp.'],[['while (i <= 3) { }','Không cập nhật i gây vòng lặp vô hạn.','Thêm i++;']],['while kiểm tra trước.','Cần điều kiện dừng.','Cập nhật biến điều khiển.'],['c-if']),
    E('c-do-while','do while','Loops','do while chạy thân trước rồi mới kiểm tra điều kiện, vì vậy thân luôn chạy ít nhất một lần. Nó phù hợp với menu cần hiển thị lần đầu.','do { statements; } while (condition);','#include <stdio.h>\n\nint main(void) {\n    int choice;\n    do {\n        choice = 0;\n        printf("Menu shown");\n    } while (choice != 0);\n    return 0;\n}','Menu được hiển thị trước khi điều kiện choice != 0 được kiểm tra.','Menu shown',['Menu tương tác','Yêu cầu nhập ít nhất một lần'],['Dấu ; sau while(condition) là bắt buộc.'],[['do { ... } while (x < 3)','Thiếu ; sau dấu ).','Thêm ;']],['Luôn chạy một lần.','Điều kiện đặt cuối.','Hợp với menu.'],['c-while']),
    E('c-for','for','Loops','for gom ba phần trên một dòng: khởi tạo, điều kiện và bước cập nhật. Nó phù hợp khi biết cách đếm hoặc số lượt lặp.','for (init; condition; update) { statements; }','#include <stdio.h>\n\nint main(void) {\n    for (int i = 1; i <= 5; i++) {\n        printf("%d ", i);\n    }\n    return 0;\n}','i bắt đầu ở 1, lặp khi i <= 5 và tăng sau mỗi thân vòng lặp.','1 2 3 4 5 ',['Duyệt mảng','Lặp số lần xác định'],['Biến khai báo trong for có scope trong vòng lặp.'],[['for (int i=0; i<5; )','Thiếu bước cập nhật có thể lặp vô hạn.','Thêm i++']],['for có init/condition/update.','Phù hợp vòng lặp đếm.','Chỉ số thường bắt đầu 0.'],['c-while']),
    E('c-nested-loops','Nested Loops','Loops','Vòng lặp lồng nhau đặt một vòng lặp bên trong vòng lặp khác. Mỗi lượt của vòng ngoài chạy toàn bộ vòng trong; thường dùng cho bảng, ma trận và cặp phần tử.','for (...) { for (...) { ... } }','#include <stdio.h>\n\nint main(void) {\n    for (int row = 1; row <= 2; row++) {\n        for (int col = 1; col <= 3; col++) printf("(%d,%d) ", row, col);\n        printf("\\n");\n    }\n    return 0;\n}','Vòng trong chạy 3 lần cho mỗi row, tạo 6 cặp tọa độ.','(1,1) (1,2) (1,3) \n(2,1) (2,2) (2,3) ',['Duyệt ma trận','Sinh tổ hợp nhỏ'],['Số phép lặp thường là tích số lượt của các vòng.'],[['for (i...) for (j...)','Dùng nhầm biến i cho cả hai vòng.','Dùng row và col riêng.']],['Vòng trong chạy trọn mỗi lượt ngoài.','Đặt tên biến chỉ số rõ.','Theo dõi độ phức tạp.'],['c-for']),
    E('c-break','break','Loops','break thoát ngay vòng lặp hoặc switch gần nhất. Nó hữu ích khi đã tìm thấy kết quả hoặc gặp điều kiện dừng đặc biệt.','while (...) { if (stop) break; }','#include <stdio.h>\n\nint main(void) {\n    for (int i = 1; i <= 10; i++) {\n        if (i == 4) break;\n        printf("%d ", i);\n    }\n    return 0;\n}','Khi i bằng 4, break kết thúc for nên chỉ in 1 2 3.','1 2 3 ',['Dừng tìm kiếm sớm','Thoát menu'],['Đừng dùng break để che giấu logic vòng lặp khó hiểu.'],[['break; outside loop','break chỉ hợp lệ trong loop hoặc switch.','Đặt trong cấu trúc phù hợp.']],['break thoát cấu trúc gần nhất.','Có thể dừng sớm.','Dùng có chủ đích.'],['c-for']),
    E('c-continue','continue','Loops','continue bỏ qua phần còn lại của lượt hiện tại và chuyển sang lượt kế tiếp. Với while, phải bảo đảm biến điều khiển vẫn được cập nhật trước continue.','for (...) { if (skip) continue; statements; }','#include <stdio.h>\n\nint main(void) {\n    for (int i = 1; i <= 5; i++) {\n        if (i == 3) continue;\n        printf("%d ", i);\n    }\n    return 0;\n}','Lượt i=3 bị bỏ qua, các lượt khác vẫn in.','1 2 4 5 ',['Lọc phần tử','Bỏ qua dữ liệu không hợp lệ'],['Tránh continue làm đường đi trở nên khó theo dõi.'],[['while (...) { if (bad) continue; }','Không tăng biến trước continue gây lặp vô hạn.','Tăng biến trước khi continue.']],['continue bỏ qua một lượt.','Không thoát toàn bộ loop.','Cẩn thận với while.'],['c-for']),
    E('c-arrays','Arrays','Arrays','Mảng lưu nhiều phần tử cùng kiểu ở các vị trí liên tiếp. Chỉ số bắt đầu từ 0; mảng n phần tử có chỉ số hợp lệ 0 đến n-1.','type arrayName[size];','#include <stdio.h>\n\nint main(void) {\n    int scores[3] = {8, 9, 10};\n    printf("%d", scores[0]);\n    return 0;\n}','scores[0] là phần tử đầu tiên. Truy cập scores[3] là vượt giới hạn.','8',['Lưu danh sách số','Dữ liệu có kích thước cố định'],['C không tự kiểm tra giới hạn mảng.'],[['scores[3]','Chỉ số nằm ngoài mảng 3 phần tử.','Dùng scores[0]..scores[2].']],['Mảng cùng kiểu.','Chỉ số bắt đầu từ 0.','Không truy cập ngoài phạm vi.'],['c-for']),
    E('c-array-elements','Array Elements','Arrays','Phần tử mảng được truy cập bằng tên mảng và chỉ số trong ngoặc vuông. Việc đọc/ghi phần tử là thao tác trực tiếp lên vùng nhớ của mảng.','array[index]','#include <stdio.h>\n\nint main(void) {\n    int values[3] = {10, 20, 30};\n    values[1] = 25;\n    printf("%d", values[1]);\n    return 0;\n}','Gán values[1] thay đổi phần tử thứ hai từ 20 thành 25.','25',['Cập nhật một bản ghi','Sửa dữ liệu theo vị trí'],['Luôn kiểm tra index trước khi ghi.'],[['values[-1] = 0;','Index âm là truy cập sai vùng nhớ.','Kiểm tra index >= 0.']],['array[index] truy cập phần tử.','Có thể đọc và ghi.','Index phải hợp lệ.'],['c-arrays']),
    E('c-array-loops','Array Loops','Arrays','Duyệt mảng thường dùng for với biến chạy từ 0 đến nhỏ hơn số phần tử. Có thể tính tổng, đếm, tìm kiếm hoặc lọc trong một lượt duyệt.','for (int i = 0; i < length; i++) { use(array[i]); }','#include <stdio.h>\n\nint main(void) {\n    int values[] = {2, 4, 6};\n    int sum = 0;\n    for (int i = 0; i < 3; i++) sum += values[i];\n    printf("%d", sum);\n    return 0;\n}','Mỗi lượt cộng một phần tử vào sum; sau ba lượt tổng là 12.','12',['Tính tổng/trung bình','Tìm max/min'],['Mảng truyền vào hàm không mang theo độ dài tự động.'],[['i <= 3','Lượt cuối dùng values[3] ngoài phạm vi.','Dùng i < 3.']],['Duyệt từ 0.','Dừng trước length.','Có thể gom phép tính trong một lượt.'],['c-arrays']),
    E('c-array-modify','Modify Array','Arrays','Mảng cho phép sửa giá trị từng phần tử qua index. Kích thước mảng tĩnh không đổi, nhưng nội dung bên trong có thể cập nhật.','array[index] = newValue;','#include <stdio.h>\n\nint main(void) {\n    int numbers[3] = {1, 2, 3};\n    for (int i = 0; i < 3; i++) numbers[i] *= 2;\n    printf("%d %d %d", numbers[0], numbers[1], numbers[2]);\n    return 0;\n}','Vòng lặp ghi lại từng phần tử sau khi nhân đôi.','2 4 6',['Chuẩn hóa dữ liệu','Áp dụng phép biến đổi hàng loạt'],['Tách số phần tử khỏi dữ liệu để tránh magic number.'],[['numbers[3] = 8;','Ghi ngoài mảng.','numbers[2] = 8;']],['Mảng có kích thước cố định.','Nội dung có thể thay đổi.','Ghi đúng index.'],['c-array-elements']),
    E('c-multidim-array','Multidimensional Arrays','Arrays','Mảng nhiều chiều là mảng của các mảng, thường biểu diễn bảng hoặc ma trận. Mỗi chiều có một index và thường được duyệt bằng vòng lặp lồng nhau.','type matrix[rows][columns];','#include <stdio.h>\n\nint main(void) {\n    int matrix[2][2] = {{1, 2}, {3, 4}};\n    printf("%d", matrix[1][0]);\n    return 0;\n}','matrix[1][0] là hàng thứ hai, cột đầu tiên nên có giá trị 3.','3',['Bảng điểm','Ma trận và ảnh dạng pixel'],['Thứ tự hàng/cột cần thống nhất.'],[['matrix[2][0]','Hàng 2 vượt mảng có 2 hàng.','Dùng index 0 hoặc 1.']],['Mỗi chiều có index.','Dùng loop lồng nhau.','Không vượt giới hạn từng chiều.'],['c-array-loops']),
    E('c-string-declaration','String Declaration','Strings','Khai báo chuỗi bằng mảng char hoặc con trỏ tới string literal. Mảng char có thể sửa nội dung; literal trỏ qua char* không nên bị ghi đè.','char name[] = "An";\nchar name[30];','#include <stdio.h>\n\nint main(void) {\n    char name[20] = "An";\n    name[0] = \'B\';\n    printf("%s", name);\n    return 0;\n}','Mảng name có vùng nhớ riêng nên name[0] có thể đổi từ A thành B.','Bn',['Lưu tên và nhãn','Xử lý dòng văn bản'],['Luôn dành chỗ cho \\0.'],[['char *name = "An"; name[0] = \'B\';','Ghi vào literal là undefined behavior.','Dùng char name[] nếu cần sửa.']],['Chuỗi là char array.','Mảng có thể sửa.','Literal không nên sửa.'],['c-strings']),
    E('c-string-input','Input String','Strings','Đọc chuỗi cần giới hạn số ký tự để bảo vệ buffer. fgets đọc cả khoảng trắng và nhận kích thước buffer; sau khi đọc có thể cần bỏ newline cuối dòng.','fgets(buffer, sizeof buffer, stdin);','#include <stdio.h>\n\nint main(void) {\n    char name[40];\n    fgets(name, sizeof name, stdin);\n    printf("%s", name);\n    return 0;\n}','fgets đọc tối đa sizeof(name)-1 ký tự và tự thêm \\0 nếu còn chỗ.','(input line)',['Nhập tên đầy đủ','Đọc câu có khoảng trắng'],['Không dùng gets; hàm này đã bị loại bỏ vì không an toàn.'],[['fgets(name, 100, stdin) với name[20]','Kích thước truyền vào vượt buffer.','fgets(name, sizeof name, stdin)']],['Giới hạn độ dài input.','fgets đọc khoảng trắng.','Luôn chừa \\0.'],['c-strings']),
    E('c-string-functions','String Functions','Strings','Thư viện string.h cung cấp các hàm xử lý chuỗi như strlen, strcpy, strcat và strcmp. Các hàm không tự cấp phát buffer, nên người lập trình phải bảo đảm vùng đích đủ lớn.','#include <string.h>\nstrlen(s); strcpy(dst, src); strcmp(a,b);','#include <stdio.h>\n#include <string.h>\n\nint main(void) {\n    char text[] = "C language";\n    printf("%zu", strlen(text));\n    return 0;\n}','strlen đếm ký tự trước \\0, không tính ký tự null.','10',['Đo, nối, sao chép và so sánh text','Xử lý tên file'],['strcpy/strcat có thể tràn buffer nếu dùng sai.'],[['strcpy(small, longText)','Đích không đủ chỗ.','Kiểm tra capacity trước khi copy.']],['Cần include string.h.','strlen không tính \\0.','Buffer phải đủ lớn.'],['c-strings']),
    E('c-string-manipulation','String Manipulation','Strings','Thao tác chuỗi là việc đọc từng char, nối chuỗi, tìm ký tự hoặc chuẩn hóa nội dung. Vì chuỗi C kết thúc bằng \\0, mọi vòng lặp chuỗi phải dừng khi gặp ký tự này hoặc khi đạt giới hạn.','for (size_t i=0; s[i] != \'\\0\'; i++) { ... }','#include <stdio.h>\n\nint main(void) {\n    char text[] = "abc";\n    for (int i = 0; text[i] != \'\\0\'; i++) text[i] -= 32;\n    printf("%s", text);\n    return 0;\n}','Mỗi ký tự thường được chuyển thành chữ hoa ASCII trong ví dụ đơn giản này.','ABC',['Đổi chữ hoa/chữ thường','Lọc ký tự'],['Chuyển chữ hoa theo ASCII không thay thế đầy đủ locale/Unicode.'],[['for (i=0; i<strlen(s); i++) s[i+1]','Có thể truy cập lệch khi sửa.','Sửa đúng vị trí s[i].']],['Chuỗi là dãy char.','Dừng ở \\0.','Giới hạn vòng lặp.'],['c-string-functions']),
    E('c-user-input','User Input với scanf','Input & Validation','scanf đọc dữ liệu theo format và ghi vào biến thông qua địa chỉ. Với int dùng %d và &age; với double dùng %lf và &value. Giá trị trả về cho biết có bao nhiêu trường đọc thành công.','int result = scanf("%d", &number);','#include <stdio.h>\n\nint main(void) {\n    int age;\n    printf("Age: ");\n    if (scanf("%d", &age) == 1) printf("You are %d", age);\n    return 0;\n}','&age cho scanf địa chỉ để ghi số vào age; kiểm tra ==1 giúp tránh dùng dữ liệu chưa hợp lệ.','You are (entered age)',['Nhập số và lựa chọn','Xây dựng form console'],['Sau scanf có thể còn newline trong stdin; xử lý trước khi đọc chuỗi.'],[['scanf("%d", age)','Thiếu &, scanf nhận địa chỉ sai.','scanf("%d", &age)']],['scanf cần format.','Biến số cần &.','Kiểm tra return value.'],['c-variables']),
    E('c-input-validation','Input Validation','Input & Validation','Validation kiểm tra dữ liệu có đúng kiểu, phạm vi và quy tắc trước khi dùng. Với scanf, kiểm tra return value; với số, kiểm tra min/max; với chuỗi, giới hạn độ dài và loại bỏ dữ liệu thừa.','if (scanf("%d", &n) != 1) { /* invalid */ }','#include <stdio.h>\n\nint main(void) {\n    int age;\n    if (scanf("%d", &age) != 1 || age < 0 || age > 130) {\n        printf("Invalid");\n    } else printf("Valid");\n    return 0;\n}','Input không phải số hoặc ngoài 0..130 bị từ chối trước khi xử lý.','Valid/Invalid',['Form nhập liệu','Bảo vệ chương trình khỏi dữ liệu xấu'],['Validation phải xảy ra ở ranh giới nhận dữ liệu.'],[['Dùng age ngay sau scanf thất bại','age có thể chưa được gán hợp lệ.','Kiểm tra return value trước.']],['Không tin input.','Kiểm tra kiểu và phạm vi.','Báo lỗi rõ cho người dùng.'],['c-user-input']),
    E('c-functions','Functions','Functions','Hàm là khối mã có tên, nhận dữ liệu qua tham số và có thể trả kết quả. Hàm giúp chia bài toán, tái sử dụng code và giới hạn phạm vi biến.','return_type name(parameters) { statements; }','#include <stdio.h>\n\nvoid greet(void) {\n    printf("Hello");\n}\n\nint main(void) {\n    greet();\n    return 0;\n}','greet chứa nhiệm vụ in lời chào; main gọi hàm thay vì lặp lại câu lệnh.','Hello',['Tách nhiệm vụ','Tạo thư viện nhỏ'],['Một hàm nên có trách nhiệm rõ ràng.'],[['void greet() { return 1; }','void không trả giá trị.','Đổi kiểu trả về thành int hoặc bỏ return value.']],['Hàm tái sử dụng code.','Tên hàm nói lên nhiệm vụ.','main cũng là một hàm.'],['c-syntax']),
    E('c-function-parameters','Function Parameters','Functions','Parameter là biến trong khai báo hàm; argument là giá trị truyền khi gọi. C mặc định truyền bản sao giá trị, nên đổi parameter không đổi biến gốc.','return_type name(type parameter) { ... }','#include <stdio.h>\n\nint add(int a, int b) { return a + b; }\nint main(void) {\n    printf("%d", add(2, 3));\n    return 0;\n}','add nhận hai bản sao 2 và 3 rồi trả tổng 5.','5',['Tách phép tính','Tạo hàm dùng nhiều dữ liệu'],['Dùng con trỏ khi muốn hàm sửa biến gốc.'],[['add(2)','Thiếu argument.','add(2, 3)']],['Parameter nhận dữ liệu.','Argument là giá trị truyền.','Mặc định truyền by value.'],['c-functions']),
    E('c-return-values','Return Values','Functions','return kết thúc hàm và gửi một giá trị về nơi gọi. Kiểu trả về phải phù hợp; hàm void không trả dữ liệu nhưng có thể dùng return; để kết thúc sớm.','type function(...) { return value; }','#include <stdio.h>\n\nint square(int n) { return n * n; }\nint main(void) {\n    int result = square(4);\n    printf("%d", result);\n    return 0;\n}','square(4) trả 16; main nhận giá trị rồi in.','16',['Tách tính toán khỏi hiển thị','Tạo API có kết quả'],['Tránh return địa chỉ của biến cục bộ.'],[['int f(void) { }','Hàm int kết thúc không return là lỗi logic/undefined.','return 0;']],['return gửi kết quả.','Kiểu phải khớp.','void không trả dữ liệu.'],['c-function-parameters']),
    E('c-function-prototypes','Function Prototypes','Functions','Prototype khai báo chữ ký hàm trước khi hàm được gọi. Compiler dùng prototype để kiểm tra số lượng và kiểu argument, đặc biệt khi định nghĩa hàm sau main.','return_type name(type, type);','#include <stdio.h>\n\nint add(int a, int b);\n\nint main(void) {\n    printf("%d", add(2, 3));\n    return 0;\n}\n\nint add(int a, int b) { return a + b; }','Prototype giúp main biết add tồn tại trước khi gặp phần định nghĩa.','5',['Tách .h và .c','Thiết kế API'],['Prototype phải khớp định nghĩa.'],[['int add(int a); rồi định nghĩa 2 tham số','Chữ ký không khớp.','Dùng cùng danh sách tham số.']],['Prototype báo trước hàm.','Compiler kiểm tra lời gọi.','Header thường chứa prototype.'],['c-functions']),
    E('c-scope','Scope','Functions','Scope là vùng code nơi tên biến hoặc hàm có thể được truy cập. Biến cục bộ thuộc block/hàm; biến toàn cục có phạm vi file hoặc rộng hơn và nên hạn chế để tránh phụ thuộc ẩn.','{ int local = 1; }','#include <stdio.h>\n\nint total = 10;\nint main(void) {\n    int local = 2;\n    printf("%d %d", total, local);\n    return 0;\n}','local chỉ tồn tại trong main; total được khai báo ngoài hàm nên main truy cập được.','10 2',['Giới hạn dữ liệu','Tránh xung đột tên'],['Ưu tiên scope nhỏ và truyền dữ liệu qua parameter.'],[['printf("%d", local) outside block','local không còn tồn tại ngoài block.','Đưa lệnh vào block hoặc truyền giá trị.']],['Scope giới hạn khả năng truy cập.','Local thường dễ kiểm soát.','Global cần dùng tiết chế.'],['c-functions']),
    E('c-recursion','Recursion','Functions','Đệ quy là hàm gọi lại chính nó. Một hàm đệ quy phải có base case để dừng và recursive case làm bài toán nhỏ dần; thiếu base case dẫn tới tràn stack.','result(n) = base; result(n) = n * result(n-1);','#include <stdio.h>\n\nint factorial(int n) {\n    if (n <= 1) return 1;\n    return n * factorial(n - 1);\n}\nint main(void) {\n    printf("%d", factorial(5));\n    return 0;\n}','factorial giảm n qua mỗi lời gọi và dừng tại n<=1; kết quả là 120.','120',['Factorial và cây thư mục','Duyệt cấu trúc tự lồng'],['Vòng lặp thường đơn giản hơn cho bài toán tuyến tính.'],[['factorial(n) gọi lại n','Không tiến tới base case.','Gọi factorial(n-1).']],['Cần base case.','Bài toán phải nhỏ dần.','Recursion dùng stack.'],['c-return-values']),
    E('c-math-functions','Math Functions','Functions','math.h cung cấp hàm toán học như sqrt, pow, fabs và floor. Các hàm nhận/trả số thực; khi build GCC có thể cần liên kết thư viện math bằng -lm.','#include <math.h>\nsqrt(x); pow(x,y);','#include <stdio.h>\n#include <math.h>\n\nint main(void) {\n    printf("%.1f", sqrt(25.0));\n    return 0;\n}','sqrt(25.0) trả 5.0; compiler có thể cần gcc main.c -lm.','5.0',['Tính hình học','Tính lãi và số đo'],['Kiểm tra domain, ví dụ sqrt số âm với số thực.'],[['sqrt(25)','Thiếu math.h hoặc dùng sai kiểu kỳ vọng.','include <math.h>']],['math.h chứa hàm toán.','Có thể cần -lm.','Kiểm tra miền giá trị.'],['c-functions']),
    E('c-memory-addresses','Memory Addresses','Pointers & Memory','Mỗi biến nằm tại một địa chỉ trong bộ nhớ. Toán tử & lấy địa chỉ; %p in địa chỉ theo dạng implementation-defined. Hiểu địa chỉ là bước đầu để hiểu pointer và truyền dữ liệu cho hàm.','&variable\n(void*)address','#include <stdio.h>\n\nint main(void) {\n    int value = 42;\n    printf("%p", (void*)&value);\n    return 0;\n}','&value là địa chỉ nơi value được lưu; địa chỉ thay đổi giữa các lần chạy.','0x...',['Debug bộ nhớ','Truyền địa chỉ cho scanf'],['Không so sánh địa chỉ như số thông thường nếu không có mục đích rõ.'],[['printf("%d", &value)','Địa chỉ không phải int.','printf("%p", (void*)&value)']],['& lấy địa chỉ.','Địa chỉ phụ thuộc execution.','Pointer dùng địa chỉ.'],['c-variables']),
    E('c-pointers','Pointers','Pointers & Memory','Con trỏ là biến lưu địa chỉ của một đối tượng. * dùng để giải tham chiếu, tức truy cập giá trị tại địa chỉ; chỉ dereference con trỏ trỏ tới vùng nhớ hợp lệ.','type *pointer = &variable;\n*pointer','#include <stdio.h>\n\nint main(void) {\n    int value = 10;\n    int *ptr = &value;\n    *ptr = 20;\n    printf("%d", value);\n    return 0;\n}','ptr giữ địa chỉ value; *ptr = 20 ghi vào value nên value đổi thành 20.','20',['Sửa dữ liệu qua hàm','Duyệt mảng và cấp phát động'],['Khởi tạo pointer bằng NULL hoặc địa chỉ hợp lệ.'],[['int *ptr; *ptr = 1;','ptr chưa trỏ vùng nhớ hợp lệ.','int value; int *ptr = &value;']],['Pointer lưu địa chỉ.','* truy cập giá trị.','Pointer sai gây lỗi nghiêm trọng.'],['c-memory-addresses']),
    E('c-pointer-variables','Pointer Variables','Pointers & Memory','Pointer variable cũng có kiểu: int* trỏ tới int, char* trỏ tới char. Kiểu giúp compiler biết số byte cần đọc khi cộng pointer hoặc dereference.','int *p;\nchar *q;','#include <stdio.h>\n\nint main(void) {\n    int number = 7;\n    int *p = &number;\n    printf("%d", *p);\n    return 0;\n}','p được khai báo là pointer tới int và *p đọc số nguyên tại địa chỉ đó.','7',['Truyền biến vào hàm','Duyệt dữ liệu kiểu cụ thể'],['Dùng NULL khi chưa có địa chỉ và kiểm tra trước khi dereference.'],[['char *p = &number;','Kiểu pointer không khớp đối tượng.','int *p = &number;']],['Pointer có kiểu.','Kiểu ảnh hưởng dereference.','Kiểm tra NULL.'],['c-pointers']),
    E('c-pointer-arrays','Pointers and Arrays','Pointers & Memory','Trong nhiều biểu thức, tên mảng suy biến thành pointer tới phần tử đầu tiên. p+i trỏ tới phần tử thứ i và *(p+i) tương đương array[i] trong phạm vi cùng mảng.','int *p = array;\n*(p + i)','#include <stdio.h>\n\nint main(void) {\n    int a[] = {10, 20, 30};\n    int *p = a;\n    printf("%d", *(p + 1));\n    return 0;\n}','p+1 trỏ tới a[1], compiler tự tính bước theo sizeof(int).','20',['Duyệt mảng bằng pointer','Xây dựng API nhận buffer'],['Không cộng pointer ra ngoài cùng một mảng.'],[['*(p + 3)','Ngoài mảng 3 phần tử.','Giới hạn i < 3.']],['Tên mảng thường là địa chỉ đầu.','Pointer arithmetic theo kiểu.','Không vượt mảng.'],['c-arrays','c-pointers']),
    E('c-pointer-functions','Pointers and Functions','Pointers & Memory','Truyền pointer vào hàm cho phép hàm sửa dữ liệu ở nơi gọi, mô phỏng truyền tham chiếu. Đây là kỹ thuật quan trọng cho swap, output nhiều giá trị và thao tác buffer.','void change(int *value) { *value = ...; }','#include <stdio.h>\n\nvoid increment(int *value) { (*value)++; }\nint main(void) {\n    int n = 4;\n    increment(&n);\n    printf("%d", n);\n    return 0;\n}','main truyền &n; hàm dereference pointer và tăng n gốc lên 5.','5',['Hàm swap','Hàm trả nhiều kết quả qua output parameter'],['Pointer parameter có thể là NULL; hãy quy định contract.'],[['increment(n)','Hàm cần int* nhưng nhận int.','increment(&n)']],['Truyền pointer để sửa dữ liệu.','& tạo địa chỉ.','* truy cập dữ liệu gốc.'],['c-pointers']),
    E('c-pointer-arithmetic','Pointer Arithmetic','Pointers & Memory','Cộng/trừ pointer di chuyển theo kích thước kiểu trỏ tới, không theo một byte cố định. Phép tính hợp lệ chủ yếu trong cùng một mảng; không cộng hai pointer với nhau.','p + n; p - q;','#include <stdio.h>\n\nint main(void) {\n    int a[3] = {4, 8, 12};\n    int *first = &a[0], *last = &a[2];\n    printf("%td", last - first);\n    return 0;\n}','last-first là 2 phần tử, không phải số byte.','2',['Tính khoảng cách phần tử','Duyệt buffer hiệu quả'],['Dùng ptrdiff_t cho hiệu số pointer.'],[['p + q','C không định nghĩa cộng hai pointer.','Dùng p + n.']],['Pointer arithmetic theo kiểu.','Chỉ cùng mảng.','Hiệu pointer là số phần tử.'],['c-pointer-arrays']),
    E('c-structures','Structures','Structures & Advanced C','struct gom nhiều trường có thể khác kiểu thành một bản ghi. Nó mô hình hóa đối tượng như Student hoặc Product mà không cần các mảng rời rạc khó đồng bộ.','struct Name { type member; };','#include <stdio.h>\n\nstruct Student { char name[20]; int age; };\nint main(void) {\n    struct Student s = {"An", 20};\n    printf("%s %d", s.name, s.age);\n    return 0;\n}','s có hai member name và age; dấu chấm truy cập member của biến struct.','An 20',['Biểu diễn bản ghi','Xây mô hình dữ liệu'],['Struct không tự bảo vệ invariant; validation vẫn cần.'],[['struct Student s; printf("%d", s.age);','s chưa được khởi tạo.','Khởi tạo s trước khi đọc.']],['struct nhóm nhiều field.','Member có kiểu riêng.','Dùng . với biến struct.'],['c-data-types']),
    E('c-struct-members','Struct Members','Structures & Advanced C','Member là trường dữ liệu trong struct. Truy cập member bằng dấu chấm với biến thường; mỗi member có thể được đọc, ghi và truyền vào hàm như một biến phù hợp kiểu.','object.member = value;','#include <stdio.h>\n\nstruct Point { int x; int y; };\nint main(void) {\n    struct Point p = {1, 2};\n    p.x = 5;\n    printf("%d %d", p.x, p.y);\n    return 0;\n}','p.x được cập nhật độc lập với p.y.','5 2',['Cập nhật thuộc tính','Tính toán trên bản ghi'],['Nếu dùng pointer struct, dùng -> thay vì .'],[['p->x với biến p','-> chỉ dành cho pointer.','p.x hoặc (&p)->x']],['Member truy cập bằng dấu . với biến.','Có thể gán lại.','Pointer dùng ->.'],['c-structures']),
    E('c-struct-arrays','Struct Arrays','Structures & Advanced C','Mảng struct lưu nhiều bản ghi cùng schema. Mỗi phần tử có thể được duyệt bằng index, rồi truy cập member để tìm, sắp xếp hoặc cập nhật danh sách.','struct Item items[count];','#include <stdio.h>\n\nstruct Product { char name[20]; int price; };\nint main(void) {\n    struct Product p[2] = {{"Pen", 10}, {"Book", 20}};\n    printf("%s %d", p[1].name, p[1].price);\n    return 0;\n}','p[1] là bản ghi thứ hai, p[1].price là giá của Book.','Book 20',['Danh sách sinh viên/sản phẩm','Lập bảng dữ liệu trong bộ nhớ'],['Truyền thêm count khi đưa mảng struct vào hàm.'],[['p[2].price','Index 2 ngoài mảng 2 phần tử.','Dùng p[0] hoặc p[1].']],['Mảng struct là danh sách bản ghi.','Index chọn bản ghi.','Member chọn trường.'],['c-structures']),
    E('c-nested-structures','Nested Structures','Structures & Advanced C','Struct có thể chứa một struct khác để biểu diễn dữ liệu nhiều tầng, như Student có Address. Truy cập theo chuỗi dấu chấm và nên tách kiểu thành các khái niệm dễ hiểu.','outer.inner.member','#include <stdio.h>\n\nstruct Address { char city[20]; };\nstruct Person { char name[20]; struct Address address; };\nint main(void) {\n    struct Person p = {"An", {"Hue"}};\n    printf("%s", p.address.city);\n    return 0;\n}','p.address.city đi qua Person rồi Address để lấy city.','Hue',['Mô hình dữ liệu phân cấp','Thông tin người dùng'],['Tránh struct lồng quá sâu nếu không cần.'],[['p.city','city thuộc address, không thuộc Person trực tiếp.','p.address.city']],['Struct có thể lồng nhau.','Truy cập theo chuỗi member.','Thiết kế model vừa đủ.'],['c-struct-members']),
    E('c-typedef','typedef','Structures & Advanced C','typedef tạo bí danh cho kiểu hiện có. Nó không tạo kiểu hoàn toàn mới nhưng làm khai báo dài, nhất là struct và function pointer, dễ đọc hơn.','typedef existing_type Alias;','#include <stdio.h>\n\ntypedef struct { char name[20]; int age; } Student;\nint main(void) {\n    Student s = {"An", 20};\n    printf("%s", s.name);\n    return 0;\n}','Sau typedef, Student là bí danh cho struct vô danh.','An',['Đặt tên model','Thiết kế public header'],['Đừng lạm dụng typedef để che mất bản chất kiểu.'],[['typedef int Number; Number x = "1";','Bí danh không đổi quy tắc kiểu.','Number x = 1;']],['typedef tạo bí danh.','Không đổi bản chất kiểu.','Hữu ích với struct.'],['c-structures']),
    E('c-enums','Enumerations','Structures & Advanced C','enum tạo tập hằng số nguyên có tên, giúp trạng thái và lựa chọn dễ đọc hơn. Giá trị mặc định bắt đầu từ 0 và có thể đặt rõ giá trị.','enum Name { FIRST, SECOND };','#include <stdio.h>\n\nenum Status { OFF, ON };\nint main(void) {\n    enum Status state = ON;\n    if (state == ON) printf("Enabled");\n    return 0;\n}','state giữ hằng ON thay vì số 1 không có ý nghĩa.','Enabled',['Trạng thái máy','Kết hợp switch'],['Enum vẫn được biểu diễn như số nguyên; validation domain vẫn cần.'],[['enum Status state = 2;','2 có thể không thuộc trạng thái đã định nghĩa.','Kiểm tra giá trị trước khi gán.']],['enum đặt tên cho hằng.','Giúp switch dễ đọc.','Giá trị nền là integer.'],['c-switch']),
    E('c-unions','Unions','Structures & Advanced C','union cho nhiều member dùng chung một vùng nhớ; tại một thời điểm chỉ một cách diễn giải dữ liệu là hợp lệ. Union tiết kiệm bộ nhớ nhưng cần biến trạng thái cho biết member đang hoạt động.','union Data { int i; float f; };','#include <stdio.h>\n\nunion Data { int i; float f; };\nint main(void) {\n    union Data data;\n    data.i = 42;\n    printf("%d", data.i);\n    return 0;\n}','data.i được ghi rồi đọc bằng cùng member; ghi data.f sau đó sẽ thay đổi cùng vùng nhớ.','42',['Variant data và protocol','Tiết kiệm bộ nhớ nhúng'],['Không đọc member khác với member vừa ghi nếu không hiểu representation.'],[['data.i=1; data.f=2.0; printf("%d",data.i)','Đọc member cũ sau khi ghi member mới.','Theo dõi active member.']],['Union dùng chung bộ nhớ.','Chỉ một member hợp lệ mỗi lúc.','Cần quản lý trạng thái.'],['c-structures']),
    E('c-memory','Memory Management','Pointers & Memory','Chương trình C dùng nhiều vùng bộ nhớ: code, global/static, stack và heap. Quản lý bộ nhớ nghĩa là biết dữ liệu sống bao lâu, ai sở hữu nó và khi nào được giải phóng.','pointer = malloc(bytes);\nfree(pointer);','#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    int *p = malloc(sizeof *p);\n    if (p) { *p = 7; printf("%d", *p); free(p); }\n    return 0;\n}','p trỏ heap sau malloc; free trả vùng nhớ về hệ thống và kết thúc ownership.','7',['Dữ liệu kích thước runtime','Bộ đệm và cấu trúc động'],['Mỗi allocation cần một ownership rõ ràng.'],[['free(p); printf("%d", *p);','Use-after-free.','Không dùng sau free.']],['Stack và heap khác nhau.','Allocation cần free.','Ownership phải rõ.'],['c-pointers']),
    E('c-stack','Stack','Pointers & Memory','Stack thường chứa biến cục bộ, tham số và thông tin gọi hàm. Vùng nhớ stack tự thu hồi khi hàm kết thúc; trả về địa chỉ biến cục bộ là sai vì object đã hết lifetime.','void f(void) { int local; }','#include <stdio.h>\n\nvoid show(void) {\n    int local = 3;\n    printf("%d", local);\n}\nint main(void) { show(); return 0; }','local chỉ tồn tại trong lần gọi show và không nên được trả địa chỉ ra ngoài.','3',['Hiểu lifetime','Debug stack overflow'],['Đệ quy quá sâu hoặc mảng cục bộ quá lớn có thể đầy stack.'],[['int *bad(void) { int x=1; return &x; }','Trả địa chỉ object đã hết lifetime.','Dùng caller-owned hoặc heap.']],['Stack tự thu hồi theo scope.','Biến cục bộ có lifetime ngắn.','Không trả địa chỉ local.'],['c-scope']),
    E('c-heap','Heap','Pointers & Memory','Heap là vùng bộ nhớ cho allocation động, sống tới khi free. Heap phù hợp khi kích thước hoặc lifetime không biết trước, nhưng mọi allocation đều tạo trách nhiệm quản lý và nguy cơ leak.','void *memory = malloc(bytes);','#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    int *numbers = malloc(3 * sizeof *numbers);\n    if (!numbers) return 1;\n    numbers[0] = 10;\n    printf("%d", numbers[0]);\n    free(numbers);\n    return 0;\n}','numbers sống trên heap sau khi main tiếp tục chạy và chỉ mất khi free.','10',['Mảng runtime','Đối tượng sống qua scope'],['Kiểm tra NULL trước khi dùng.'],[['int *p = malloc(...); return;','Leak nếu không free.','free(p) trước khi rời ownership.']],['Heap do lập trình viên quản lý.','Có thể sống qua scope.','Leak là mất tài nguyên.'],['c-memory']),
    E('c-malloc','malloc()','Pointers & Memory','malloc cấp một vùng nhớ động chưa khởi tạo và trả void*. Số byte nên tính bằng số phần tử nhân sizeof phần tử; kết quả NULL nghĩa là cấp phát thất bại.','type *p = malloc(count * sizeof *p);','#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    int *p = malloc(3 * sizeof *p);\n    if (!p) return 1;\n    p[0] = 11;\n    printf("%d", p[0]);\n    free(p);\n    return 0;\n}','sizeof *p tự theo kiểu int của p và tránh lặp tên kiểu khi refactor.','11',['Mảng động','Buffer nhận input'],['malloc không khởi tạo giá trị; không đọc trước khi ghi.'],[['int *p = malloc(3);','Có thể cấp thiếu byte cho 3 int.','malloc(3 * sizeof *p)']],['malloc chưa khởi tạo.','Kiểm tra NULL.','free đúng ownership.'],['c-heap']),
    E('c-calloc','calloc()','Pointers & Memory','calloc cấp vùng nhớ cho nhiều phần tử và khởi tạo toàn bộ byte về 0. Nó nhận count và size mỗi phần tử, hữu ích khi muốn mảng bắt đầu ở trạng thái zero.','type *p = calloc(count, sizeof *p);','#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    int *p = calloc(3, sizeof *p);\n    if (!p) return 1;\n    printf("%d", p[1]);\n    free(p);\n    return 0;\n}','p[1] có byte bằng 0; với int thông thường biểu diễn số 0.','0',['Tạo bảng đếm','Khởi tạo mảng zero'],['calloc không thay thế validation của dữ liệu.'],[['calloc(3, sizeof(int*))','Cấp theo kích thước pointer thay vì int.','calloc(3, sizeof *p)']],['calloc nhận count và size.','Vùng nhớ được zero-init theo byte.','Vẫn phải free.'],['c-malloc']),
    E('c-realloc','realloc()','Pointers & Memory','realloc thay đổi kích thước allocation. Vùng nhớ có thể được mở rộng tại chỗ hoặc chuyển sang địa chỉ mới; dùng pointer tạm để không làm mất allocation cũ nếu realloc thất bại.','tmp = realloc(pointer, newSize);','#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    int *p = malloc(2 * sizeof *p);\n    if (!p) return 1;\n    int *tmp = realloc(p, 4 * sizeof *p);\n    if (!tmp) { free(p); return 1; }\n    p = tmp; p[3] = 4;\n    printf("%d", p[3]);\n    free(p);\n    return 0;\n}','Gán realloc vào tmp bảo toàn p khi hệ thống không cấp được kích thước mới.','4',['Mảng tăng trưởng','Buffer động'],['realloc(ptr, 0) có hành vi phụ thuộc chuẩn/implementation; xử lý rõ theo contract.'],[['p = realloc(p, size); if (!p) ...','Mất địa chỉ cũ khi thất bại.','Dùng tmp.']],['realloc có thể đổi địa chỉ.','Dùng pointer tạm.','Kiểm tra thất bại.'],['c-malloc']),
    E('c-free','free()','Pointers & Memory','free kết thúc ownership của vùng nhớ do malloc/calloc/realloc cấp. Sau free, pointer trở thành dangling pointer; không được dereference và có thể gán NULL để giảm dùng nhầm.','free(pointer);\npointer = NULL;','#include <stdlib.h>\n\nint main(void) {\n    int *p = malloc(sizeof *p);\n    if (!p) return 1;\n    *p = 9;\n    free(p);\n    p = NULL;\n    return 0;\n}','Gán NULL sau free làm trạng thái “không còn sở hữu vùng nhớ” rõ hơn.','(no output)',['Dọn tài nguyên','Tránh memory leak'],['free(NULL) an toàn; double free pointer không NULL là lỗi.'],[['free(p); free(p);','Double free.','free(p); p = NULL;']],['Mỗi allocation cần free.','Không dùng sau free.','NULL giúp biểu đạt trạng thái.'],['c-realloc']),
    E('c-file-handling','File Handling','Files & Tools','File handling cho phép dữ liệu tồn tại sau khi chương trình kết thúc. FILE* đại diện stream; mở file, kiểm tra lỗi, đọc/ghi, rồi đóng bằng fclose.','FILE *f = fopen(path, mode);\nfclose(f);','#include <stdio.h>\n\nint main(void) {\n    FILE *f = fopen("demo.txt", "w");\n    if (!f) return 1;\n    fputs("Hello file\\n", f);\n    fclose(f);\n    return 0;\n}','fopen tạo/mở demo.txt, fputs ghi và fclose đóng stream để flush dữ liệu.','(file created)',['Lưu cấu hình','Lưu dữ liệu ứng dụng'],['Đường dẫn và quyền ghi phụ thuộc môi trường.'],[['FILE *f=fopen(...); fputs(...,f);','Không kiểm tra NULL.','if (f) { ... }']],['File lưu dữ liệu lâu dài.','Kiểm tra fopen.','Luôn fclose.'],['c-output']),
    E('c-fopen','fopen()','Files & Tools','fopen mở stream theo mode: r đọc file có sẵn, w tạo/ghi đè, a ghi nối cuối. Các mode có dấu + cho phép đọc và ghi; b dùng cho binary trên hệ hỗ trợ.','fopen("path", "r|w|a");','#include <stdio.h>\n\nint main(void) {\n    FILE *f = fopen("demo.txt", "a");\n    if (!f) return 1;\n    fputs("more\\n", f);\n    fclose(f);\n    return 0;\n}','Mode a giữ nội dung cũ và ghi thêm ở cuối; mode w có thể xóa nội dung cũ.','(appended)',['Chọn chiến lược lưu file','Ghi log'],['Không dùng w nếu muốn giữ dữ liệu hiện có.'],[['fopen("data.txt","w") để append','w ghi đè file.','Dùng mode "a"']],['Mode quyết định hành vi.','Kiểm tra FILE*.','Mode w có thể mất dữ liệu.'],['c-file-handling']),
    E('c-fclose','fclose()','Files & Tools','fclose đóng stream, flush buffer và giải phóng tài nguyên file. Mỗi fopen thành công cần một fclose tương ứng, kể cả sau khi đọc/ghi lỗi.','int status = fclose(file);','#include <stdio.h>\n\nint main(void) {\n    FILE *f = fopen("demo.txt", "w");\n    if (!f) return 1;\n    fputs("data", f);\n    printf("%d", fclose(f) == 0);\n    return 0;\n}','fclose trả 0 khi đóng thành công; kiểm tra giúp phát hiện lỗi flush/IO.','1',['Quản lý tài nguyên','Xác nhận ghi file'],['Không dùng FILE* sau fclose.'],[['fclose(f); fprintf(f,...);','Stream đã đóng.','Mở lại trước khi dùng.']],['fclose giải phóng stream.','Kiểm tra return value.','Không dùng sau đóng.'],['c-fopen']),
    E('c-read-file','Read File','Files & Tools','Đọc file có thể dùng fgetc để đọc char, fgets để đọc dòng hoặc fscanf để đọc theo format. Luôn kiểm tra EOF và xử lý lỗi phân biệt với kết thúc file khi cần.','while (fgets(buffer, sizeof buffer, file)) { ... }','#include <stdio.h>\n\nint main(void) {\n    FILE *f = fopen("demo.txt", "r");\n    char line[80];\n    if (!f) return 1;\n    while (fgets(line, sizeof line, f)) printf("%s", line);\n    fclose(f);\n    return 0;\n}','fgets trả NULL khi hết file hoặc lỗi; mỗi dòng được xử lý trong vòng lặp.','(file lines)',['Đọc cấu hình','Import dữ liệu text'],['Không dùng feof trước khi đọc; kiểm tra kết quả hàm đọc.'],[['while (!feof(f)) fgets(...)','Có thể xử lý lặp thêm một lần.','while (fgets(...))']],['Có nhiều cách đọc.','Kiểm tra kết quả đọc.','Đóng file sau khi dùng.'],['c-fopen']),
    E('c-write-file','Write File','Files & Tools','Ghi file dùng fputc cho một ký tự, fputs cho chuỗi hoặc fprintf cho chuỗi format. Chỉ ghi sau khi fopen thành công và kiểm tra lỗi nếu dữ liệu quan trọng.','fprintf(file, "format", values);','#include <stdio.h>\n\nint main(void) {\n    FILE *f = fopen("scores.txt", "w");\n    if (!f) return 1;\n    fprintf(f, "score=%d\\n", 95);\n    fclose(f);\n    return 0;\n}','fprintf thay %d bằng 95 và ghi vào stream thay vì stdout.','(file written)',['Xuất báo cáo','Lưu điểm'],['fclose giúp flush nhưng không thay thế kiểm tra lỗi hệ thống file.'],[['fprintf(NULL, "x")','Dereference stream NULL.','Kiểm tra f trước.']],['fprintf ghi theo format.','Mode w tạo/ghi đè.','Kiểm tra lỗi IO.'],['c-fopen']),
    E('c-append-file','Append File','Files & Tools','Append là ghi thêm vào cuối file mà không xóa nội dung trước. Mở bằng mode a; mỗi lần ghi thường thêm newline nếu muốn các bản ghi tách dòng.','FILE *f = fopen("log.txt", "a");','#include <stdio.h>\n\nint main(void) {\n    FILE *f = fopen("log.txt", "a");\n    if (!f) return 1;\n    fputs("new record\\n", f);\n    fclose(f);\n    return 0;\n}','Mỗi lần chạy thêm một record ở cuối log.txt.','(record appended)',['Log sự kiện','Lưu lịch sử thay đổi'],['Append không bảo đảm atomicity khi nhiều process cùng ghi.'],[['fopen("log.txt","w")','Mode w xóa log cũ.','Dùng "a"']],['a ghi nối cuối.','Giữ dữ liệu cũ.','Thêm delimiter/newline.'],['c-fopen']),
    E('c-file-errors','File Errors','Files & Tools','Lỗi file có thể do đường dẫn sai, thiếu quyền, file không tồn tại hoặc thiết bị đầy. Kiểm tra con trỏ trả về, return value và dùng perror để in lý do hệ thống.','if (!file) { perror("fopen"); return 1; }','#include <stdio.h>\n\nint main(void) {\n    FILE *f = fopen("missing.txt", "r");\n    if (!f) { perror("fopen"); return 1; }\n    fclose(f);\n    return 0;\n}','perror thêm thông tin lỗi hệ thống vào thông báo “fopen”.','fopen: No such file or directory',['Chẩn đoán IO','Báo lỗi dễ hành động'],['Không hiện đường dẫn nhạy cảm trong log public.'],[['if (!f) printf("ok")','Báo thành công khi fopen thất bại.','Báo lỗi và return.']],['IO có thể thất bại.','Kiểm tra mọi bước.','perror giúp chẩn đoán.'],['c-file-handling']),
    E('c-preprocessor','Preprocessor','Files & Tools','Preprocessor xử lý chỉ thị trước compiler. #include chèn nội dung header; #define tạo macro; #if/#ifdef điều khiển biên dịch theo điều kiện.',' #define NAME value\n#include <header.h>','#include <stdio.h>\n#define LIMIT 3\n\nint main(void) {\n    printf("%d", LIMIT);\n    return 0;\n}','LIMIT được thay bằng 3 trước khi compiler phân tích code. Macro không có type checking như biến const.','3',['Cấu hình build','Chia code nhiều platform'],['Dùng ngoặc trong macro có tham số.'],[['#define SQUARE(x) x*x','SQUARE(2+3) thành 2+3*2+3.','Dùng #define SQUARE(x) ((x)*(x))']],['Preprocessor chạy trước compiler.','include dùng header.','Macro cần viết cẩn thận.'],['c-syntax']),
    E('c-header-files','Header Files','Files & Tools','Header chứa declaration, type và macro dùng chung; source .c chứa definition. Include guard hoặc #pragma once giúp tránh khai báo lặp trong nhiều file.','#ifndef MY_HEADER_H\n#define MY_HEADER_H\n...\n#endif','#include <stdio.h>\n\nint main(void) {\n    puts("Header declares puts");\n    return 0;\n}','stdio.h khai báo puts để compiler biết chữ ký hàm trước khi gọi.','Header declares puts',['Chia module','Tạo thư viện nội bộ'],['Header public nên có guard và interface tối thiểu.'],[['Định nghĩa global trong header','Mỗi file include tạo nhiều definition.','Đặt extern declaration hoặc definition trong .c']],['Header cung cấp interface.','Source cung cấp definition.','Guard tránh include lặp.'],['c-preprocessor']),
    E('c-command-line','Command Line Arguments','Files & Tools','main có thể nhận argc là số đối số và argv là mảng chuỗi. argv[0] thường là tên chương trình; phải kiểm tra argc trước khi truy cập argv[i].','int main(int argc, char *argv[])','#include <stdio.h>\n\nint main(int argc, char *argv[]) {\n    if (argc > 1) printf("%s", argv[1]);\n    return 0;\n}','Khi chạy ./app hello, argc lớn hơn 1 và argv[1] chứa hello.','hello',['CLI tool','Script hóa tác vụ'],['Đối số luôn là chuỗi; dùng strtol để parse số có kiểm tra.'],[['printf("%s", argv[1]) without argc','Truy cập thiếu phần tử.','if (argc > 1)']],['argc đếm đối số.','argv chứa chuỗi.','Kiểm tra argc.'],['c-functions']),
    E('c-bitwise','Bitwise Operators','Files & Tools','Toán tử bit thao tác biểu diễn nhị phân của số nguyên: &, |, ^, ~, << và >>. Chúng phù hợp với bitmask, cờ trạng thái và giao tiếp phần cứng.','flags & MASK\nflags |= MASK;','#include <stdio.h>\n\nint main(void) {\n    unsigned flags = 0;\n    flags |= 1u << 2;\n    printf("%u", (flags & (1u << 2)) != 0);\n    return 0;\n}','Bật bit 2 bằng OR rồi kiểm tra bằng AND; kết quả là 1.','1',['Cờ quyền','Thanh ghi và protocol nhị phân'],['Dùng unsigned để tránh bất ngờ khi shift.'],[['1 << 31 với int signed','Có thể undefined/implementation-defined.','Dùng unsigned và giới hạn shift.']],['Bitwise khác logical.','Mask chọn bit.','Cẩn thận signed shift.'],['c-logical']),
    E('c-null','NULL','Errors & Practice','NULL là hằng con trỏ biểu diễn “không trỏ tới object hợp lệ”. Kiểm tra NULL trước dereference và gán NULL sau khi giải phóng giúp trạng thái pointer rõ hơn.','if (pointer == NULL) { ... }','#include <stdio.h>\n\nint main(void) {\n    int *p = NULL;\n    if (p == NULL) puts("No object");\n    return 0;\n}','p chưa trỏ object nên nhánh kiểm tra an toàn được thực hiện.','No object',['Biểu diễn trạng thái rỗng','Bảo vệ API pointer'],['NULL không phải chuỗi "NULL" và không được dereference.'],[['*p khi p==NULL','Dereference null pointer.','if (p) { *p; }']],['NULL biểu diễn không có object.','Kiểm tra trước khi dùng.','Không dereference NULL.'],['c-pointers']),
    E('c-error-handling','Error Handling','Errors & Practice','C không có exception tích hợp; hàm thường báo lỗi qua return value, errno, NULL hoặc out parameter. Caller phải kiểm tra ngay, giữ thông tin lỗi và chọn cách phục hồi/phản hồi.','if (result == ERROR) { /* handle */ }','#include <stdio.h>\n#include <errno.h>\n\nint main(void) {\n    FILE *f = fopen("missing.txt", "r");\n    if (!f) { perror("open"); return errno; }\n    fclose(f);\n    return 0;\n}','Hàm trả NULL; perror đọc thông tin lỗi gần nhất và main trả mã thất bại.','open: ...',['Thiết kế API có lỗi rõ','Báo lỗi cho CLI'],['Đừng nuốt lỗi hoặc chỉ in “something went wrong”.'],[['if (fopen(...)) { }','Không giữ FILE* để đóng/đọc.','Gán và kiểm tra result.']],['C báo lỗi qua contract.','Caller phải kiểm tra.','Giữ ngữ cảnh lỗi.'],['c-file-errors']),
    E('c-debugging','Debugging','Errors & Practice','Debugging là quy trình tái hiện lỗi, thu hẹp nguyên nhân, quan sát trạng thái và kiểm tra bản sửa. Compiler warnings, printf tạm thời và debugger đều là công cụ; test case nhỏ giúp lỗi lộ rõ.','gcc -g -Wall main.c -o main','#include <stdio.h>\n\nint main(void) {\n    int a = 2, b = 3;\n    printf("debug: a=%d b=%d\\n", a, b);\n    printf("sum=%d", a + b);\n    return 0;\n}','-g tạo thông tin debug; printf cho thấy dữ liệu thực trước phép tính.','debug: a=2 b=3\nsum=5',['Tái hiện bug','Kiểm tra giả thuyết'],['Xóa debug output trước bản phát hành hoặc dùng logger có mức.'],[['Sửa nhiều chỗ cùng lúc','Không biết bản sửa nào có tác dụng.','Sửa nhỏ rồi chạy test.']],['Tái hiện trước khi sửa.','Sửa một giả thuyết mỗi lần.','Test lại sau bản sửa.'],['c-compile-errors']),
    E('c-random','Random Numbers','Errors & Practice','rand() tạo chuỗi số giả ngẫu nhiên xác định theo seed. srand(time(NULL)) giúp các lần chạy khác nhau; giá trị rand()%n có bias trong một số mục đích, không dùng cho mật mã.','srand(seed);\nint value = rand();','#include <stdio.h>\n#include <stdlib.h>\n#include <time.h>\n\nint main(void) {\n    srand((unsigned)time(NULL));\n    printf("%d", rand() % 10);\n    return 0;\n}','rand()%10 tạo một giá trị trong khoảng thực tế 0..9, phù hợp demo đơn giản.','0..9',['Game nhỏ','Dữ liệu thử nghiệm'],['Không dùng rand cho password/token bảo mật.'],[['srand(time(NULL)) inside loop','Seed lại liên tục tạo chuỗi kém ngẫu nhiên.','Seed một lần ở đầu.']],['rand là giả ngẫu nhiên.','Seed một lần.','Không dùng cho crypto.'],['c-functions']),
    E('c-date-time','Date and Time','Errors & Practice','time.h cung cấp time_t, localtime/gmtime, struct tm và strftime để lấy, tách và định dạng thời gian. Cần chú ý timezone và tính hợp lệ của con trỏ trả về.','#include <time.h>\ntime_t now = time(NULL);','#include <stdio.h>\n#include <time.h>\n\nint main(void) {\n    time_t now = time(NULL);\n    struct tm *info = localtime(&now);\n    if (info) printf("%04d", info->tm_year + 1900);\n    return 0;\n}','tm_year tính từ 1900 nên cần cộng 1900 để ra năm hiện tại.','YYYY',['Timestamp log','Hiển thị ngày giờ'],['Thời gian local phụ thuộc timezone máy.'],[['printf("%d", info->tm_year)','Quên offset 1900.','info->tm_year + 1900']],['time_t lưu thời điểm.','struct tm tách thành phần.','Timezone ảnh hưởng output.'],['c-error-handling']),
    E('c-storage-classes','Storage Classes','Errors & Practice','Storage class ảnh hưởng linkage, scope và lifetime. auto là mặc định cho local; static giữ giá trị giữa các lần gọi hoặc giới hạn linkage file; extern khai báo definition ở nơi khác; register chỉ là gợi ý cũ.','static int calls;\nextern int shared;','#include <stdio.h>\n\nint next_count(void) {\n    static int count = 0;\n    return ++count;\n}\nint main(void) {\n    printf("%d %d", next_count(), next_count());\n    return 0;\n}','count không bị tạo lại từ 0 sau mỗi lần gọi vì static local giữ lifetime toàn chương trình.','1 2',['Bộ đếm trạng thái nội bộ','Chia biến giữa module'],['static không tự làm code thread-safe.'],[['Dùng global cho mọi trạng thái','Tạo phụ thuộc ẩn và khó test.','Giới hạn scope hoặc truyền state.']],['static ảnh hưởng lifetime/linkage.','extern không tạo storage.','Scope và lifetime là hai ý khác nhau.'],['c-scope']),
    E('c-fixed-width','Fixed-width Integers','Errors & Practice','stdint.h cung cấp kiểu int8_t, uint32_t, int64_t... khi cần kích thước chính xác. Kiểu này hữu ích cho file format, network packet và thanh ghi, nơi int không đủ đảm bảo cùng kích thước trên mọi nền tảng.','#include <stdint.h>\nuint32_t counter = 0;','#include <stdio.h>\n#include <stdint.h>\n\nint main(void) {\n    uint32_t counter = 4000000000u;\n    printf("%u", counter);\n    return 0;\n}','uint32_t đảm bảo ít nhất 32 bit không dấu; format chính xác nên tham khảo PRIu32 khi portable tuyệt đối.','4000000000',['Binary protocol','Dữ liệu lưu trữ portable'],['Không giả định format specifier giữa mọi kiểu fixed-width; dùng inttypes.h khi cần.'],[['int counter = 4000000000u','int có thể không chứa giá trị.','uint32_t counter']],['stdint.h cho kích thước rõ.','Chọn signed/unsigned đúng.','Portable code cần format đúng.'],['c-data-types']),
    E('c-projects','C Projects','Errors & Practice','Project là nơi ghép nhiều khái niệm thành sản phẩm nhỏ: phân rã yêu cầu, thiết kế dữ liệu, tách hàm, kiểm tra input, lưu file và debug. Bắt đầu nhỏ rồi mở rộng theo test.','main -> menu -> functions -> data -> file','#include <stdio.h>\n\nint main(void) {\n    puts("Mini project: grade book");\n    puts("1. Add  2. List  3. Save");\n    return 0;\n}','Một project menu nên tách mỗi lựa chọn thành hàm và dùng struct cho bản ghi thay vì dồn tất cả vào main.','Mini project: grade book',['Quản lý điểm','Danh bạ','To-do console'],['Viết test cho từng chức năng trước khi ghép menu.'],[['Dồn toàn bộ code vào main','Khó đọc, khó test và khó sửa.','Tách hàm theo nhiệm vụ.']],['Chia bài toán.','Thiết kế dữ liệu trước.','Test từng phần.'],['c-functions','c-structures']),
    E('c-exercises','C Exercises','Errors & Practice','Bài tập biến kiến thức thành kỹ năng. Với mỗi đề, xác định input, output, constraint và test case; viết giải pháp đơn giản trước, sau đó mới tối ưu.','read -> validate -> process -> print','#include <stdio.h>\n\nint main(void) {\n    int a, b;\n    if (scanf("%d %d", &a, &b) == 2) printf("%d", a + b);\n    return 0;\n}','Mẫu đọc–kiểm tra–xử lý–in giúp bài tập có cấu trúc và dễ debug.','sum',['Luyện sau mỗi lesson','Chuẩn bị phỏng vấn'],['Test cả số âm, số 0, giá trị lớn và input sai.'],[['Chỉ test một ví dụ','Bỏ sót trường hợp biên.','Viết thêm test case.']],['Đọc đề thành input/output.','Chia thành bước.','Test trường hợp biên.'],['c-input-validation']),
    E('c-quiz','C Quiz','Errors & Practice','Quiz kiểm tra hiểu khái niệm, cú pháp và khả năng đọc code. Hãy giải thích vì sao đáp án đúng thay vì chỉ nhớ chữ cái; câu sai cho biết phần cần ôn lại.','question -> options -> answer -> explanation','#include <stdio.h>\n\nint main(void) {\n    int answer = 2;\n    printf("Review topic %d", answer);\n    return 0;\n}','Một quiz tốt gắn với code thật và có explanation, không chỉ hỏi thuộc lòng thuật ngữ.','Review topic 2',['Tự kiểm tra sau chương','Ôn trước project'],['Làm lại câu sai sau khi đọc phần khái niệm.'],[['Chọn đáp án theo may mắn','Không biết lỗ hổng kiến thức.','Đọc explanation và thử code.']],['Quiz đo hiểu biết.','Giải thích quan trọng.','Có thể retry.'],['c-exercises']),
    E('c-reference','C Reference','Errors & Practice','Reference là bảng tra cứu nhanh keyword, format specifier, hàm thư viện và toán tử. Reference bổ trợ lesson: đọc khái niệm trước, dùng reference khi cần kiểm tra chi tiết chữ ký hoặc giới hạn.','symbol -> signature -> contract','#include <stdio.h>\n\nint main(void) {\n    printf("%d", 42);\n    return 0;\n}','Tra cứu printf cần biết header stdio.h, format và kiểu return; không nên chỉ copy một dòng gọi hàm.','42',['Tra cứu khi code','Ôn phỏng vấn'],['Luôn đọc contract về ownership, return và lỗi.'],[['Chỉ nhớ tên hàm','Không biết input/output và lỗi.','Đọc signature + contract.']],['Reference trả lời “dùng thế nào”.','Lesson trả lời “vì sao”.','Kết hợp cả hai.'],['c-output']),
    E('c-study-plan','C Study Plan','Errors & Practice','Study plan chia việc học theo giai đoạn: cú pháp và output, biến và điều kiện, loop/mảng, hàm, pointer, struct/file rồi project. Mỗi buổi nên có đọc, gõ code, bài tập và ôn lại.','learn -> practice -> review -> build','#include <stdio.h>\n\nint main(void) {\n    puts("Read, type, practice, review");\n    return 0;\n}','Nhịp học ngắn nhưng đều giúp củng cố trí nhớ và giảm việc học dồn.','Read, type, practice, review',['Lập lịch tự học','Theo dõi progress'],['Ưu tiên hiểu và làm được trước khi học chủ đề nâng cao.'],[['Chạy qua bài mà không thực hành','Kiến thức nhanh quên.','Làm một bài nhỏ sau mỗi lesson.']],['Học theo thứ tự prerequisite.','Thực hành ngay.','Ôn bằng project.'],['c-intro'])
  ];
  window.cLessons = lessons;
})();
